cpp.code:
int countDigits(long long n) {
    if (n == 0) return 1;
    if (n < 0) n = -n;
    int c = 0;
    while (n) { c++; n /= 10; }
    return c;
}

java.code:
static int countDigits(long n) {
    if (n == 0) return 1;
    n = Math.abs(n);
    int c = 0;
    while (n > 0) { c++; n /= 10; }
    return c;
}

go.code:
func countDigits(n int64) int {
    if n == 0 { return 1 }
    if n < 0 { n = -n }
    c := 0
    for n > 0 { c++; n /= 10 }
    return c
}
